                { interval: "50,000 km", timeLimit: "N/A", task: "Injector Value Inspection", details: "Use VCDS to check injector deviation values. High negative values indicate the injectors are dripping fuel.", parts: ["Diagnostic"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, 
                { interval: "150,000 km", timeLimit: "N/A", task: "Injector Copper Seals", details: "Replace copper crush washers to prevent massive blow-by and thick 'black death' carbon buildup around the injectors.", parts: ["4x Copper Seals"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "150 - 250 EUR" }, 
                { interval: "100,000 km", timeLimit: "N/A", task: "DPF Ash Mass Check", details: "Check the DPF ash volume using VCDS diagnostic software. If full, it must be professionally cleaned or replaced.", parts: ["Diagnostic"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, 
                { interval: "100,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "Inspect and replace the main drive belt and tensioner pulley.", parts: ["Belt Kit", "Tensioner"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 - 120 EUR" }, 
                { interval: "N/A", timeLimit: "N/A", task: "Silica Bag Removal", details: "Locate the 'Silicat' bag inside the coolant expansion tank and safely remove it before it bursts.", parts: ["None"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" } 
