                { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter Replacement", details: "The turbocharger requires maximum airflow. A clogged filter severely limits power and increases soot production.", parts: ["Air Filter Element"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 - 40 EUR" }, 
                { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Air Filter Replacement", details: "Replace filter to keep HVAC blower motor clear of debris.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "20 - 35 EUR" }, 
                { interval: "30,000 km", timeLimit: "2 years", task: "Fuel Filter Maintenance", details: "Absolutely critical to protect the high-pressure fuel pump and delicate injectors from any contamination.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "40 - 70 EUR" } 
