        { partName: "Haldex AWD Pump Screen Kit", category: "Drivetrain", oem: { brand: "BorgWarner", code: "Haldex Gen 5 Kit", approxPrice: "80 EUR" }, crossRef: { brand: "BorgWarner", code: "Haldex Gen 5 Kit", approxPrice: "80 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/0cq598549", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=0cq598549" }, note: "Not listed by Audi, but mandatory to physically clean the pump screen." }
