            { interval: "80,000 km", timeLimit: "N/A", task: "Ignition Coil Replacement", details: "Proactively replace the ignition coils. Engine heat breaks down their internal insulation, leading to sudden failure.", parts: ["4x Eldor Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "120 - 160 EUR" }, 
            { interval: "80,000 km", timeLimit: "5 years", task: "PCV Valve Replacement", details: "Crucial preventative maintenance. A failing PCV valve will blow out the rear main seal.", parts: ["PCV Assembly"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "100 - 150 EUR" }, 
            { interval: "120,000 km", timeLimit: "N/A", task: "Thermostat & Water Pump Module", details: "Replace the fragile plastic thermostat housing and water pump before they crack and cause catastrophic overheating.", parts: ["Water Pump Module"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 - 500 EUR" }, 
            { interval: "100,000 km", timeLimit: "N/A", task: "HPFP Cam Follower Inspection", details: "Remove the high-pressure fuel pump and inspect the mechanical roller follower for wear.", parts: ["Roller Follower"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, 
            { interval: "100,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "Inspect and replace the auxiliary drive belt and tensioner.", parts: ["Belt Kit", "Tensioner"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "100 - 150 EUR" } 
