        { partName: "Engine Air Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "5Q0129620B", approxPrice: "35 EUR" }, crossRef: { brand: "Mann-Filter", code: "C30005", approxPrice: "20 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/5q0129620b", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=5q0129620b" }, note: "Replace frequently to ensure maximum turbo efficiency." },
        { partName: "DQ381 Transmission Filter", category: "Drivetrain", oem: { brand: "Audi Genuine", code: "0GC325183A", approxPrice: "45 EUR" }, crossRef: { brand: "Febi Bilstein", code: "109869", approxPrice: "25 EUR", source: "Premium Aftermarket", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/0gc325183a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=0gc325183a" }, note: "Crucial to replace during the 60k km DSG fluid change." },
        { partName: "PCV Valve Assembly", category: "Engine", oem: { brand: "Audi Genuine", code: "06K103495BP", approxPrice: "160 EUR" }, crossRef: { brand: "Vaico", code: "V10-3867", approxPrice: "85 EUR", source: "Premium Aftermarket", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/06k103495bp", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=06k103495bp" }, note: "Guards against massive vacuum leaks and blown rear main seals. Gen 4 specific." },
        { partName: "Haldex AWD Pump Screen Kit", category: "Drivetrain", oem: { brand: "BorgWarner", code: "Haldex Gen 6 Kit", approxPrice: "80 EUR" }, crossRef: { brand: "BorgWarner", code: "Haldex Gen 6 Kit", approxPrice: "80 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/0cq598549", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=0cq598549" }, note: "Not listed by Audi, but mandatory to physically clean the pump screen." },
        { partName: "High-Pressure Fuel Pump", category: "Fuel", oem: { brand: "Audi Genuine", code: "06L127025N", approxPrice: "350 EUR" }, crossRef: { brand: "Hitachi", code: "HPP0012", approxPrice: "180 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/06l127025n", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=06l127025n" }, note: "Failing HPFP causes severe fuel cuts under heavy acceleration." },
        { partName: "Cabin Air Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "5Q0819653", approxPrice: "30 EUR" }, crossRef: { brand: "Mann-Filter", code: "CUK26009", approxPrice: "15 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/5q0819653", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=5q0819653" }, note: "Activated carbon filter for odor reduction." }
