    torqueSpecs: [ 
        { part: "Engine Oil Drain Plug", value: "30 Nm", note: "Always replace the copper crush washer to prevent weeping from the cast aluminum oil pan." }, 
        { part: "Glow Plugs", value: "15 Nm", note: "Use high-temperature ceramic anti-seize paste and torque strictly into a warm engine to prevent snapping the fragile ceramic plugs." }, 
        { part: "Wheel Bolts", value: "120 Nm", note: "Tighten precisely using a torque wrench in a star pattern." }, 
        { part: "Valve Cover Bolts", value: "9 Nm", note: "Tighten evenly in a crisscross pattern to prevent warping the composite plastic cover." }, 
        { part: "Water Pump Bolts", value: "15 Nm", note: "Tighten evenly to ensure the metal gasket seals perfectly against the engine block." }, 
        { part: "Fuel Injector Clamps", value: "8 Nm + 180 degrees", note: "Crucial torque-to-yield stretch bolt. Must be replaced to prevent massive compression blow-by." }, 
        { part: "High-Pressure Fuel Pump Bolts", value: "20 Nm", note: "Tighten evenly to ensure the pump seats perfectly and the timing belt aligns correctly." }, 
        { part: "DSG Transmission Drain Plug", value: "45 Nm", note: "Ensure the fluid is at the correct temperature (35-45°C) before checking the level." }, 
        { part: "Haldex Pump Bolts", value: "9 Nm", note: "Tighten evenly to ensure the O-rings seal perfectly." }, 
        { part: "Intake Manifold Bolts", value: "20 Nm", note: "Tighten in a spiral pattern from the center out." } 
    ],
    engineeringData: { blockDesign: "Cast Iron inline-4 (EA288 architecture). An incredibly rigid, extremely heavy block designed specifically to withstand immense diesel combustion pressures while offering incredible thermal stability.", crankshaft: "Forged Steel, featuring 5 massive main bearings and 4 counterweights, providing incredible balancing and smoothness for a diesel engine.", pistonSpeed: "14.2 m/s @ 4500 RPM. A very conservative piston speed ensuring exceptionally low cylinder wall wear and contributing to the engine's monumental durability.", alternator: "140A Bosch variant, driven by a standard ribbed serpentine belt.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy featuring an internal oil cooling gallery specifically designed to manage the extreme heat generated by the VNT turbocharger and common rail injection.", wristPinDiameter: "26 mm, highly robust and thick to handle massive low-end torque.", connectingRodLength: "144 mm, manufactured using a fracture-split technique for absolutely perfect cap alignment.", rodBoltSize: "M8.5 x 1.0, strictly one-time-use stretch bolts.", crankMainJournal: "54.0 mm, providing massive surface area for the oil film.", crankRodJournal: "47.8 mm, perfectly optimized for high-torque delivery.", rodRatio: "1.67, minimizing cylinder wall side-loading perfectly." }, cylinderHead: { combustionChamberVol: "In-piston bowl design typical for direct-injection diesels, optimized for the high-pressure spray pattern.", intakePortFlow: "16-valve DOHC design (4 valves per cylinder). Features advanced swirl flaps in the intake manifold to induce extreme turbulence at low RPMs for cleaner combustion.", valveSizes: "Intake: 26.6 mm / Exhaust: 24.5 mm.", valveStemDiameter: "5.5 mm.", camshaftDuration: "Fixed duration, belt-driven overhead cams.", lifterType: "Hydraulic lifters paired with low-friction roller finger followers.", specialFeature: "Features an incredibly complex thermal management system with micro-circuits in the cylinder head to drastically accelerate engine warm-up and reduce cold-start emissions." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets spray a continuous stream of oil to prevent the piston crowns from incinerating under load.", oilPumpType: "Chain-driven, fully variable displacement vane pump located in the massive oil pan.", thermostatOpening: "Electronic map-controlled rotary slide thermal management module.", oilCooler: "Standard water-to-oil heat exchanger mounted near the oil filter housing." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "Up to 2000 Bar on the fuel rail, guaranteeing supreme atomization.", injectors: "4x high-speed electromagnetic solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "Approx. 450 Nm (The MQ350 manual transmission handles this easily, and the EA288 block takes it effortlessly).", maxSafePowerStock: "Approx. 210 hp (The factory internal components are completely unstressed at this point, but the VNT turbocharger and restrictive DPF become physical bottlenecks).", maxSafeRPM: "5000 RPM. Diesel combustion speed physically limits higher revs.", weakestLink: "The restrictive Diesel Particulate Filter (DPF), the highly sensitive high-pressure fuel pump, and the complex EGR system." }, electrical: { coils: "Compression ignition; utilizes 4x high-voltage glow plugs to assist cold starts and DPF regeneration.", ecu: "Bosch EDC17. Highly advanced, integrating extreme boost control, complex DPF monitoring, and injection timing." } },
    recommendedParts: { description: "Maintenance on the EA288 2.0 TDI revolves entirely around proactive timing belt services, addressing the heavily flawed EGR system, and protecting the DSG transmission.", parts: [ 
        { category: "Timing Belt & Water Pump Kit", brand: "Continental / INA", note: "CRITICAL. Do not wait for 210,000km. Replace at 150,000km to prevent water pump seizure and belt snapping." }, 
        { category: "EGR Cooler & Valve Assembly", brand: "BorgWarner / Pierburg", note: "Prone to clogging with soot and leaking coolant internally. Requires replacement if car loses coolant without external leaks." }, 
        { category: "DPF Differential Pressure Sensor", brand: "Bosch", note: "Fails frequently due to exhaust heat. A failed sensor will permanently prevent DPF regeneration." }, 
        { category: "DQ381 Transmission Filter & Fluid", brand: "ZF Genuine / Febi", note: "Crucial to drain the pan and replace the external filter to save the wet-clutch mechatronic unit." }, 
        { category: "Fuel Filter", brand: "Mann-Filter", note: "Change strictly every 30k km to protect the highly expensive and fragile high-pressure fuel pump." }, 
        { category: "Engine Oil Filter", brand: "Mann-Filter", note: "High capacity fleece element. Use only high-quality VW 507.00 synthetic low-ash oil to protect the DPF." }, 
        { category: "Glow Plugs", brand: "Beru / Bosch", note: "Must be fully functional. A single failed glow plug will prevent the DPF from regenerating in cold weather." }, 
        { category: "AdBlue / DEF Pump & Heater", brand: "Bosch", note: "Failure leads to a non-bypassable ECU engine start lockout." } 
    ] },
