        { partName: "DPF Pressure Sensor", category: "Emissions", oem: { brand: "Audi Genuine", code: "04L906051G", approxPrice: "85 EUR" }, crossRef: { brand: "Bosch", code: "0281006005", approxPrice: "45 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/04l906051g", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=04l906051g" }, note: "Crucial for correct DPF regeneration. Fails frequently." },
        { partName: "Glow Plugs", category: "Ignition", oem: { brand: "Audi Genuine", code: "03L905315", approxPrice: "35 EUR" }, crossRef: { brand: "Beru", code: "GE133", approxPrice: "18 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/03l905315", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=03l905315" }, note: "Requires 4 units. Essential for DPF regeneration." },
        { partName: "Fuel Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "5Q0127177C", approxPrice: "45 EUR" }, crossRef: { brand: "Mann-Filter", code: "PU8014", approxPrice: "22 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/5q0127177c", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=5q0127177c" }, note: "Replace every 30k km to protect the high-pressure fuel pump." },
        { partName: "Engine Oil Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "03N115562", approxPrice: "20 EUR" }, crossRef: { brand: "Mann-Filter", code: "HU7020z", approxPrice: "12 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/03n115562", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=03n115562" }, note: "High capacity fleece element. Use low-ash oil." },
        { partName: "DQ381 Transmission Filter", category: "Drivetrain", oem: { brand: "Audi Genuine", code: "0GC325183A", approxPrice: "45 EUR" }, crossRef: { brand: "Febi Bilstein", code: "109869", approxPrice: "25 EUR", source: "Premium Aftermarket", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/0gc325183a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=0gc325183a" }, note: "Crucial to replace during the 60k km DSG fluid change." },
        { partName: "Engine Air Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "5Q0129620B", approxPrice: "35 EUR" }, crossRef: { brand: "Mann-Filter", code: "C30005", approxPrice: "20 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/5q0129620b", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=5q0129620b" }, note: "Replace frequently to ensure maximum turbo efficiency." },
        { partName: "Cabin Air Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "5Q0819653", approxPrice: "30 EUR" }, crossRef: { brand: "Mann-Filter", code: "CUK26009", approxPrice: "15 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/5q0819653", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=5q0819653" }, note: "Activated carbon filter for odor reduction." }
