        { partName: "Spark Plugs", category: "Ignition", oem: { brand: "Audi Genuine", code: "06H905601A", approxPrice: "25 EUR" }, crossRef: { brand: "NGK", code: "R7437-9", approxPrice: "22 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/06h905601a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=06h905601a" }, note: "Must be replaced strictly every 60k km. 5 units required." },
        { partName: "Ignition Coils", category: "Ignition", oem: { brand: "Audi Genuine", code: "06E905115F", approxPrice: "55 EUR" }, crossRef: { brand: "Eldor", code: "R8 Red Coils", approxPrice: "35 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/06e905115f", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=06e905115f" }, note: "Provides a much stronger spark, highly recommended upgrade. 5 units required." },
        { partName: "Engine Oil Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "06D115562", approxPrice: "22 EUR" }, crossRef: { brand: "Mann-Filter", code: "HU719/6x", approxPrice: "12 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/06d115562", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=06d115562" }, note: "High capacity fleece element." },
        { partName: "DQ500 Transmission Filter", category: "Drivetrain", oem: { brand: "Audi Genuine", code: "0BH325183B", approxPrice: "45 EUR" }, crossRef: { brand: "Febi Bilstein", code: "109869", approxPrice: "25 EUR", source: "Premium Aftermarket", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/0bh325183b", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=0bh325183b" }, note: "Crucial to replace during the 60k km DSG fluid change." },
        { partName: "High-Pressure Fuel Pump", category: "Fuel", oem: { brand: "Audi Genuine", code: "07K127025A", approxPrice: "450 EUR" }, crossRef: { brand: "Hitachi", code: "HPP0012", approxPrice: "250 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/07k127025a", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=07k127025a" }, note: "Failing HPFP causes severe fuel cuts under heavy acceleration. Upgrade internals for tuning." },
        { partName: "Haldex AWD Pump Screen Kit", category: "Drivetrain", oem: { brand: "BorgWarner", code: "Haldex Gen 5 Kit", approxPrice: "80 EUR" }, crossRef: { brand: "BorgWarner", code: "Haldex Gen 5 Kit", approxPrice: "80 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/0cq598549", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=0cq598549" }, note: "Not listed by Audi, but mandatory to physically clean the pump screen." },
        { partName: "Engine Air Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "8V0129620", approxPrice: "45 EUR" }, crossRef: { brand: "BMC", code: "FB845/20", approxPrice: "80 EUR", source: "Performance Aftermarket", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/8v0129620", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=8v0129620" }, note: "High-flow panel filter strongly recommended for the 2.5 TFSI." },
        { partName: "Cabin Air Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "5Q0819653", approxPrice: "30 EUR" }, crossRef: { brand: "Mann-Filter", code: "CUK26009", approxPrice: "15 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/5q0819653", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=5q0819653" }, note: "Activated carbon filter for odor reduction." }
